import { format } from "prettier";
import { build } from "esbuild";
import { writeFile } from "node:fs/promises";
const { outputFiles } = await build({
  entryPoints: ["scripts/widget-markdown-client.js"],
  bundle: true,
  write: false,
  format: "iife",
  globalName: "widgetMarkdown",
  minify: true,
  target: "es2020",
  legalComments: "none",
});
await writeFile(
  "apps/api/src/widget-markdown.generated.ts",
  await format(
    "// Generated by node scripts/build-widget-markdown.mjs; do not edit.\n// Bundles marked (MIT), see LICENSES/marked.txt.\nexport const widgetMarkdownCode = " +
      JSON.stringify(outputFiles[0].text) +
      ";\n",
    { parser: "typescript" },
  ),
);
